function postForm(){const p=state.posts.find(p=>p.id===editing);return pageHead(p?'Modifica contenuto':'Crea un contenuto','1. Scrivi il testo · 2. Aggiungi i formati · 3. Scegli quando pubblicare')+`<form data-form="compose" data-id="${esc(p?.id||'')}"><div class="composer"><section><span class="step-label">1 · IL CONTENUTO</span><div class="grid"><label>Sede<select name="office_id">${options(state.offices,p?.office_id)}</select></label><label>Giorno / raccolta<input name="day_label" value="${esc(p?.day_label||'')}" placeholder="Es. Lunedì"></label></div><label>Titolo interno<input name="title" value="${esc(p?.title||'')}" placeholder="Es. La casa dei tuoi sogni" required maxlength="500"></label><label>Testo principale<textarea name="body" class="caption" required maxlength="5000" placeholder="Cosa vuoi raccontare?">${esc(p?.body||'')}</textarea></label><p class="muted">Puoi personalizzare il testo per ciascun social nello slot a fianco.</p><details><summary>Media precedenti e link esterni</summary>${p?mediaPreview(p):''}<label>Link immagini / video, uno per riga<textarea name="media">${esc((p?.media||[]).filter(m=>!m.startsWith('asset:')).join('\n'))}</textarea></label><p>Le immagini precedenti restano disponibili per i canali senza uno slot dedicato.</p></details></section><section><span class="step-label">2 · I FORMATI SOCIAL</span><div class="slot-tabs">${Object.entries(formats).map(([k,f])=>`<button type="button" class="${k===activeSlot?'active':''}" data-action="slot" data-id="${k}">${f.icon} ${f.name}<span id="slot-check-${k}">${draftSlots[k]?.media?' ✓':''}</span></button>`).join('')}</div><div id="slot-panel">${slotMarkup(activeSlot)}</div></section></div><div class="save-bar"><span id="saveState">Le modifiche saranno salvate nella libreria</span><div class="actions"><button class="secondary" name="intent" value="save">Salva bozza</button><button name="intent" value="schedule">Salva e scegli data →</button></div></div></form>`}
function calendar(){const jobs=state.jobs.filter(j=>(!calendarChannel||j.channel===calendarChannel)&&(!calendarStatus||j.status===calendarStatus));let start=new Date(calendarDate.getFullYear(),calendarDate.getMonth(),1),count=42;if(calendarView==='week'){start=new Date(calendarDate);start.setDate(start.getDate()-(start.getDay()+6)%7);count=7}else start.setDate(start.getDate()-(start.getDay()+6)%7);const title=calendarView==='month'?calendarDate.toLocaleDateString('it-IT',{month:'long',year:'numeric'}):`Settimana del ${start.toLocaleDateString('it-IT')}`;const days=Array.from({length:count},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d});return pageHead('Calendario editoriale','Tutte le date, i social e gli stati di pubblicazione in un unico posto.',action('approve-pending','','Approva tutte le bozze pianificate')+action('plan-post','','＋ Programma contenuto',''))+`<section class="calendar-shell"><div class="calendar-toolbar"><div class="actions">${action('cal-prev','','‹')}${action('cal-today','','Oggi')}${action('cal-next','','›')}<h2>${title}</h2></div><div class="actions">${action('cal-month','','Mese',calendarView==='month'?'':'secondary')}${action('cal-week','','Settimana',calendarView==='week'?'':'secondary')}</div></div><div class="filter-bar"><label>Social<select id="calendarChannel"><option value="">Tutti i social</option>${channels.map(c=>`<option ${calendarChannel===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Stato<select id="calendarStatus"><option value="">Tutti gli stati</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===calendarStatus?'selected':''}>${v}</option>`).join('')}</select></label><p class="muted">Orari: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}<br><span class="badge">Da approvare</span> non significa invio attivo.</p></div><div class="calendar-scroll"><div class="calendar-grid ${calendarView}">${['Lun','Mar','Mer','Gio','Ven','Sab','Dom'].map(d=>`<div class="weekday">${d}</div>`).join('')}${days.map(d=>{const key=dayKey(d),items=jobs.filter(j=>dayKey(new Date(j.scheduled_at*1000))===key);return `<div class="calendar-day ${d.getMonth()!==calendarDate.getMonth()&&calendarView==='month'?'outside':''} ${key===dayKey(new Date())?'today':''}"><button class="day-number" data-action="cal-day" data-id="${key}" aria-label="Programma il ${key}">${d.getDate()} <span>＋</span></button>${items.map(j=>`<button class="calendar-event ${j.status}" data-action="job-detail" data-id="${esc(j.id)}">${j.previews?.[0]?`<img src="${esc(j.previews[0])}" alt="">`:''}<span><b>${new Date(j.scheduled_at*1000).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})} · ${esc(channelLabel(j.channel))}</b><strong>${esc(j.title)}</strong><small>${labels[j.status]||esc(j.status)}</small></span></button>`).join('')}</div>`}).join('')}</div></div></section>${schedulePost!==null?schedulePanel():''}<div id="jobDetail"></div>`}
function schedulePanel(){const p=state.posts.find(p=>p.id===schedulePost)||state.posts[0];return `<section id="schedulePanel"><div class="page-head"><div><h2>Un contenuto, tutti i tuoi social</h2><p>Seleziona le destinazioni. Scegli uno o più orari al giorno. Un solo clic per approvare tutte le destinazioni.</p></div>${action('close-schedule','','Chiudi')}</div>${p?`<form data-form="batch-schedule" data-request="${crypto.randomUUID()}"><fieldset id="batchPosts"><legend>Contenuti da programmare</legend><label><input id="batchAllPosts" type="checkbox"> Seleziona tutti i contenuti di ${esc(officeName(p.office_id))}</label>${state.posts.filter(x=>x.office_id===p.office_id).map(x=>`<label><input name="batchPost" type="checkbox" value="${esc(x.id)}" ${x.id===p.id?'checked':''}> ${esc(x.title)}</label>`).join('')}</fieldset><label>Data iniziale (ora usata nelle altre modalità)<input id="batchDate" type="datetime-local" value="${selectedDay||dayKey(new Date(Date.now()+86400000))}T10:00" required></label><label>Distanza tra i contenuti<select id="batchSpacing"><option value="daily">Più contenuti al giorno, agli orari scelti</option><option value="1">Un contenuto al giorno, alla stessa ora</option><option value="0">Tutti alla stessa data e ora</option><option value="7">Un contenuto alla settimana</option></select></label><label>Orari giornalieri<input id="batchTimes" value="13:00, 19:00" placeholder="13:00, 19:00"></label><p class="muted">Con “Più contenuti al giorno” i contenuti selezionati occupano gli orari in ordine: primo alle 13, secondo alle 19, terzo il giorno dopo. Non duplica lo stesso contenuto.</p><div id="batchTargets">${batchTargets(p)}</div><label><input id="batchApprove" type="checkbox" checked> Approva gli invii alle destinazioni selezionate</label><p>Ogni social utilizza il proprio testo e formato. Le destinazioni non valide bloccano l’intero gruppo, senza creare invii parziali.</p><button>Approva e programma le destinazioni selezionate</button></form>`:'<p>Crea prima un contenuto.</p>'}</section>`}

function batchDateAt(base,spacing,times,index){
 const date=new Date(base);if(!Number.isFinite(date.getTime()))throw Error('Scegli la data iniziale');
 if(spacing==='daily'){
  const slots=[...new Set(times.split(/[,;\s]+/).filter(Boolean))].sort();
  if(!slots.length||slots.length>12||slots.some(t=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(t)))throw Error('Scrivi fino a 12 orari validi, ad esempio 13:00, 19:00');
  const [h,m]=slots[index%slots.length].split(':').map(Number);date.setDate(date.getDate()+Math.floor(index/slots.length));date.setHours(h,m,0,0);
  if(date.getHours()!==h||date.getMinutes()!==m)throw Error('Orario non valido per il cambio ora: scegli un altro orario');
 }else{if(!['0','1','7'].includes(spacing))throw Error('Frequenza non valida');date.setDate(date.getDate()+index*Number(spacing));}
 return date;
}
function batchTargets(p){return channels.flatMap(ch=>state.connections.filter(c=>c.enabled&&c.office_id===p.office_id&&c.platform===(ch.startsWith('Instagram')?'Instagram':ch.split(' ')[0])).map(c=>`<label class="target-choice"><input type="checkbox" name="batchTarget" value="${esc(c.id)}" data-channel="${esc(ch)}"> <b>${esc(ch)}</b> · ${esc(c.name)}</label>`)).join('')||'<p>Collega prima un account per questa sede.</p>'}
function schedulePreview(p,ch){const key=Object.keys(formats).find(k=>formats[k].channel===ch),slot=p.slots?.[key],src=slot?.preview||p.previews?.[0];return `<div class="schedule-preview">${src?`<img src="${esc(src)}" alt="Anteprima per ${esc(ch)}">`:''}<div><span class="badge">${esc(officeName(p.office_id))} · ${esc(ch)}</span><h3>${esc(p.title)}</h3><p class="clamp">${esc(slot?.body||p.body)}</p>${ch==='Instagram Reel'?'<p class="warn">Una copertina non basta: questo formato richiede un video.</p>':''}${ch==='TikTok'?'<p class="warn">Invio automatico disponibile con Buffer collegato e pubblicazione abilitata per la sede. In alternativa usa la pubblicazione assistita.</p>':''}</div></div>`}
function jobDetail(id){const j=state.jobs.find(j=>j.id===id);if(!j)return;const p=state.posts.find(p=>p.id===j.post_id);$('jobDetail').innerHTML=`<section><div class="page-head"><div><span class="badge">${labels[j.status]}</span><h2>${esc(j.title)}</h2><p>${esc(j.channel)} · ${new Date(j.scheduled_at*1000).toLocaleString('it-IT')}</p></div>${action('close-detail','','Chiudi')}</div>${mediaPreview(j)}${assistedPanel(j)}${j.last_error?`<p class="warn">${esc(j.last_error)}</p>`:''}${!j.remote?.buffer_attempted&&['draft','scheduled','error','cancelled'].includes(j.status)?`<form data-form="edit-job" data-id="${esc(j.id)}"><label>Testo della pubblicazione<textarea name="body" required>${esc(j.body)}</textarea></label><label>Data e ora<input name="scheduled" type="datetime-local" value="${localTime(j.scheduled_at)}" required></label><button>Salva e rimetti in approvazione</button></form><div class="actions">${action('approve',j.id,'Approva invio')}${j.status!=='cancelled'?action('cancel',j.id,'Annulla programmazione'):''}</div>`:`<pre>${esc(j.body)}</pre>`}</section>`;$('jobDetail').scrollIntoView({behavior:'smooth',block:'start'})}
function importer(){return pageHead('Importa le tue grafiche','Il pacchetto rimane organizzato per giorno, contenuto e social.')+`<section><h2>1. Scegli il pacchetto ZIP</h2><p>Riconosce cartelle Facebook, Instagram, LinkedIn, Stories_FB_IG, Reel_FB_IG e TikTok. Legge didascalie, ISTRUZIONI_CONTENUTO.txt e piani editoriali TXT/CSV con titolo, data, orario e social.</p><label>Sede di destinazione<select id="importOffice">${options(state.offices)}</select></label><label>Settimana di pubblicazione<input id="importWeek" type="date"></label><label><input id="importShiftWeek" type="checkbox"> Usa la settimana scelta anche se il piano contiene date precedenti</label><label><input id="importApprove" type="checkbox" checked> Approva automaticamente i contenuti importati e programma gli orari dello ZIP</label><p>Fuso orario: Italia (Europe/Rome). Le date del file sono mantenute, salvo la scelta di spostarle alla settimana indicata. Gli orari del piano (anche più al giorno) restano invariati.</p><label class="zip-drop">Seleziona ZIP (massimo 150 MB)<input id="zipFile" type="file" accept=".zip,application/zip"></label><p class="muted">I contenuti vengono preapprovati. Se nello ZIP ci sono date e orari riconosciuti, gli invii validi vengono programmati automaticamente. Gli altri restano in libreria, con le informazioni mancanti segnalate.</p><div id="zipPreview"></div></section>`}
async function imageInfo(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),im=new Image();im.onload=()=>resolve({width:im.naturalWidth,height:im.naturalHeight,preview:url});im.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Immagine non valida'))};im.src=url})}
function keepSlotText(){if($('slotBody'))draftSlots[activeSlot]={...(draftSlots[activeSlot]||{}),body:$('slotBody').value}}
async function selectSlotFile(file){if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type))throw Error('Scegli una immagine PNG, JPG o WebP');if(file.size>15000000)throw Error('Massimo 15 MB per immagine');keepSlotText();const info=await imageInfo(file);draftFiles[activeSlot]=file;draftSlots[activeSlot]={...(draftSlots[activeSlot]||{}),...info};formDirty=true;$('slot-panel').innerHTML=slotMarkup(activeSlot);$('slot-check-'+activeSlot).textContent=' ✓';const f=formats[activeSlot];if(info.width!==f.w||info.height!==f.h)toast(`Immagine ${info.width} × ${info.height}. Lo slot suggerisce ${f.size}; l’immagine non verrà ritagliata.`)}
// Read central directory rather than file headers (supports ZIP data descriptors).
async function zipRead(file){if(file.size>150000000)throw Error('ZIP oltre 150 MB');const a=new Uint8Array(await file.arrayBuffer()),v=new DataView(a.buffer);let end=-1;for(let i=a.length-22;i>=Math.max(0,a.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('Archivio ZIP non valido');const total=v.getUint16(end+10,true);if(total>600)throw Error('Massimo 600 file per ZIP');let pos=v.getUint32(end+16,true),sum=0;const entries=[];for(let i=0;i<total;i++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('Indice ZIP non valido');const flags=v.getUint16(pos+8,true),method=v.getUint16(pos+10,true),compressed=v.getUint32(pos+20,true),size=v.getUint32(pos+24,true),n=v.getUint16(pos+28,true),extra=v.getUint16(pos+30,true),comment=v.getUint16(pos+32,true),offset=v.getUint32(pos+42,true),name=new TextDecoder().decode(a.slice(pos+46,pos+46+n));pos+=46+n+extra+comment;if(!/\.(png|jpe?g|webp|txt|csv)$/i.test(name)||name.startsWith('__MACOSX/'))continue;if(flags&1||![0,8].includes(method))throw Error('ZIP cifrato o compressione non supportata');if(name.split('/').includes('..')||name.startsWith('/'))throw Error('Percorso ZIP non valido');sum+=size;if(size>15000000||sum>250000000)throw Error('Archivio troppo grande una volta estratto');const begin=offset+30+v.getUint16(offset+26,true)+v.getUint16(offset+28,true);entries.push({name,size,method,bytes:a.slice(begin,begin+compressed)})}return entries}
async function unzipEntry(e){let bytes=e.bytes;if(e.method===8){const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader();let chunks=[],length=0;while(true){const {value,done}=await reader.read();if(done)break;length+=value.length;if(length>e.size||length>15000000){await reader.cancel();throw Error('Dimensione ZIP non valida')}chunks.push(value)}bytes=new Uint8Array(await new Blob(chunks).arrayBuffer())}if(bytes.length!==e.size)throw Error('File ZIP incompleto');return bytes}
let zipGeneration=0;
async function inspectZip(file){zipItems=[];zipOffice='';const entries=await zipRead(file),groups=new Map(),folderMap={Facebook:'facebook',Instagram:'instagram',LinkedIn:'linkedin',Stories_FB_IG:'story',Reel_FB_IG:'reel',TikTok:'tiktok'};
 const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('');const documents=[];
 for(const e of entries){const path=e.name.split('/'),folder=path.at(-2),k=folderMap[folder];if(/\.(txt|csv)$/i.test(e.name)&&!['TESTO_DA_COPIARE.txt','SCRIPT_VIDEO.txt'].includes(path.at(-1)))documents.push({name:e.name,text:new TextDecoder().decode(await unzipEntry(e))});if(!k||path.length<4)continue;const group=path.slice(0,-2).join('/');if(!groups.has(group))groups.set(group,{title:path.at(-3).replace(/^\d+_/,'').replaceAll('_',' '),day_label:path.at(-4).replace(/^\d+_/,'').replaceAll('_',' '),group,slots:{}});const item=groups.get(group),slot=item.slots[k]||(item.slots[k]={});if(/\.(png|jpe?g|webp)$/i.test(e.name)){const bytes=await unzipEntry(e),type=/\.png$/i.test(e.name)?'image/png':/\.webp$/i.test(e.name)?'image/webp':'image/jpeg';slot.file=new File([bytes],path.at(-1),{type});Object.assign(slot,await imageInfo(slot.file))}else if(path.at(-1)==='TESTO_DA_COPIARE.txt')slot.body=new TextDecoder().decode(await unzipEntry(e))}
 zipItems=[...groups.values()].filter(x=>Object.values(x.slots).some(s=>s.file));if(!zipItems.length)throw Error('Nessuna grafica riconosciuta. Usa cartelle per contenuto e social come nel pacchetto Aversa.');
 for(const [i,p] of zipItems.entries()){p.digest=digest;p.index=i;p.documents=documents.filter(d=>d.name.startsWith(p.group+'/')||!d.name.includes('/ISTRUZIONI_CONTENUTO.txt')).map(d=>({...d,local:d.name.startsWith(p.group+'/')}))}
 await previewZip();
}
async function previewZip(){const generation=++zipGeneration,office=$('importOffice').value,week=$('importWeek').value;const items=zipItems;$('zipPreview').textContent='Lettura di giorni e orari…';
 for(const p of items){const r=await api('import/preview',{office_id:office,title:p.title,day_label:p.day_label,documents:p.documents,week,shift_week:$('importShiftWeek').checked});p.schedule=r.schedule;p.warnings=r.warnings}
 if(generation!==zipGeneration)return;
 $('zipPreview').innerHTML=`<h2>2. Importa e programma</h2><p><b>${items.length} contenuti · ${items.reduce((n,x)=>n+Object.values(x.slots).filter(s=>s.file).length,0)} grafiche</b>. Controlla le destinazioni: premendo Importa autorizzi gli invii alle date indicate.</p><div class="import-list">${items.map((x,i)=>`<div><img src="${esc(Object.values(x.slots).find(s=>s.preview).preview)}" alt=""><span><small>${esc(x.day_label)}</small><b>${esc(x.title)}</b>${(x.schedule||[]).map((r,j)=>`<label>${esc(r.channel)} · ${new Date(r.scheduled).toLocaleString('it-IT',{timeZone:'Europe/Rome'})}<select id="zipTarget-${i}-${j}">${importTargets(office,r.channel)}</select></label>`).join('')}${(x.warnings||[]).map(w=>`<small>${esc(w)}</small>`).join('')}</span></div>`).join('')}</div>${action('import-pack','','Importa con queste impostazioni','')}<p id="importProgress" role="status"></p>`;
}
function importTargets(office,channel){const platform=channel.split(' ')[0],cs=state.connections.filter(c=>c.office_id===office&&c.platform===platform&&c.enabled);return (cs.length===1?'':`<option value="">${cs.length?'Scegli account':'Nessun account collegato'}</option>`)+cs.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}
async function importPack(){zipBusy=true;let done=0,total=0,warnings=[];try{const office=zipOffice||$('importOffice').value;zipOffice=office;const approved=$('importApprove').checked;$('importOffice').disabled=true;$('zipFile').disabled=true;$('importWeek').disabled=true;$('importApprove').disabled=true;$('importShiftWeek').disabled=true;
 for(const [i,p] of zipItems.entries()){if(p.saved){done++;total+=p.scheduledCount||0;warnings.push(...(p.importWarnings||[]));continue}$('importProgress').textContent=`Importazione ${done+1} di ${zipItems.length}: ${p.title}`;const slots={};for(const [k,v] of Object.entries(p.slots)){if(!v.file)continue;if(!v.media){const r=await api('upload',{office_id:office,data:await file64(v.file)});v.media=r.media}slots[k]={media:v.media,body:v.body||'',width:v.width,height:v.height}}
 p.id=p.id||[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(p.digest+office+p.group)))].map(x=>x.toString(16).padStart(2,'0')).join('');
 const schedule=(p.schedule||[]).map((r,j)=>({...r,connection_id:$('zipTarget-'+i+'-'+j).value}));
 const r=await api('import/post',{id:p.id,office_id:office,title:p.title,day_label:p.day_label,body:p.slots.instagram?.body||p.slots.facebook?.body||p.title,media:[],slots,auto_approve:approved,schedule});p.saved=true;p.scheduledCount=r.scheduled||0;p.importWarnings=[...(p.warnings||[]),...(r.warnings||[])].map(w=>p.title+': '+w);done++;total+=p.scheduledCount;warnings.push(...p.importWarnings)}
 $('zipPreview').innerHTML=`<h2>Importazione completata</h2><p>${done} contenuti in libreria · ${total} invii programmati.</p>${warnings.length?`<h3>Da completare</h3><ul>${warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}${action('open-calendar','','Vedi calendario')}`;zipItems=[];toast('Importazione completata');const fresh=await api('state');state=fresh;
 }finally{zipBusy=false;if($('importOffice'))$('importOffice').disabled=zipItems.some(p=>p.saved);for(const id of ['zipFile','importWeek','importApprove','importShiftWeek'])if($(id))$(id).disabled=false}}
document.addEventListener('input',e=>{if(e.target.closest('[data-form="compose"]'))formDirty=true});
document.addEventListener('change',async e=>{try{if(e.target.id==='slotFile')await selectSlotFile(e.target.files[0]);if(e.target.id==='zipFile'){if(!e.target.files[0])return;$('zipPreview').textContent='Lettura del pacchetto…';await inspectZip(e.target.files[0])}if(['importWeek','importOffice','importShiftWeek'].includes(e.target.id)&&zipItems.length)await previewZip();if(e.target.id==='dayFilter')filterArchive();if(['calendarChannel','calendarStatus'].includes(e.target.id)){calendarChannel=$('calendarChannel').value;calendarStatus=$('calendarStatus').value;render()}if(['scheduleContent','scheduleChannel'].includes(e.target.id)){const f=e.target.form,p=state.posts.find(p=>p.id===f.elements.post_id.value);$('schedulePreview').innerHTML=schedulePreview(p,f.elements.channel.value);$('scheduleAccount').innerHTML=importTargets(p.office_id,f.elements.channel.value)}}catch(err){toast(err.message);if(e.target.id==='zipFile')$('zipPreview').textContent='Importazione non avviata.'}});
document.addEventListener('dragover',e=>{if(e.target.closest('.slot-upload'))e.preventDefault()});
document.addEventListener('drop',async e=>{if(!e.target.closest('.slot-upload'))return;e.preventDefault();try{await selectSlotFile(e.dataTransfer.files[0])}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{const f=e.target,type=f.dataset.form;if(!['compose','visual-job'].includes(type))return;e.preventDefault();e.stopImmediatePropagation();const intent=e.submitter?.value;const bs=[...f.querySelectorAll('button')];bs.forEach(b=>b.disabled=true);try{const d=Object.fromEntries(new FormData(f));if(type==='compose'){keepSlotText();for(const [k,file] of Object.entries(draftFiles)){toast(`Caricamento ${formats[k].name}…`);const r=await api('upload',{office_id:d.office_id,data:await file64(file)});draftSlots[k].media=r.media;delete draftFiles[k]}const old=state.posts.find(p=>p.id===f.dataset.id),media=[...(old?.media||[]).filter(m=>m.startsWith('asset:')),...(d.media||'').split('\n').map(s=>s.trim()).filter(Boolean)];const r=await api('post',{...d,id:f.dataset.id,media,slots:draftSlots});formDirty=false;editing=null;tab=intent==='schedule'?'calendar':'archive';schedulePost=intent==='schedule'?r.id:null;await load();if(intent==='schedule')$('schedulePanel')?.scrollIntoView({behavior:'smooth'})}else{const p=state.posts.find(p=>p.id===d.post_id);await api('job',{...d,office_id:p.office_id,scheduled:new Date(d.scheduled).toISOString()});calendarDate=new Date(d.scheduled);schedulePost=null;await load()}toast(type==='compose'?'Contenuto salvato':'Contenuto aggiunto al calendario')}catch(err){toast(err.message)}finally{bs.forEach(b=>b.disabled=false)}},true);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(zipBusy&&(b.dataset.tab||a)){e.stopImmediatePropagation();toast('Attendi il completamento dell’importazione');return}
 if(b.dataset.tab){if(formDirty&&!confirm('Hai modifiche non salvate. Vuoi uscire senza salvarle?')){e.stopImmediatePropagation();return}formDirty=false;schedulePost=null;if(b.dataset.tab==='new'){editing=null;resetComposer()}return}
 const handled=['compose','edit-post','slot','clear-slot','open-import','import-pack','open-calendar','plan-post','cal-prev','cal-next','cal-today','cal-month','cal-week','cal-day','close-schedule','job-detail','close-detail'];if(!handled.includes(a))return;e.stopImmediatePropagation();b.disabled=true;try{if(a==='compose'||a==='edit-post'){editing=a==='compose'?null:id;resetComposer();tab='new';render();$('page').scrollIntoView({block:'start'})}else if(a==='slot'){keepSlotText();activeSlot=id;$('slot-panel').innerHTML=slotMarkup(id);document.querySelectorAll('.slot-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.id===id))}else if(a==='clear-slot'){keepSlotText();draftSlots[id]={body:draftSlots[id]?.body||''};delete draftFiles[id];formDirty=true;$('slot-panel').innerHTML=slotMarkup(id);$('slot-check-'+id).textContent=''}else if(a==='open-import'){tab='importer';render()}else if(a==='import-pack')await importPack();else if(a==='open-calendar'){tab='calendar';schedulePost=null;render()}else if(a==='plan-post'){schedulePost=id;tab='calendar';render();$('schedulePanel')?.scrollIntoView({behavior:'smooth'})}else if(a==='close-schedule'){schedulePost=null;render()}else if(a==='job-detail')jobDetail(id);else if(a==='close-detail')$('jobDetail').innerHTML='';else{if(a==='cal-prev'||a==='cal-next'){const n=a==='cal-prev'?-1:1;if(calendarView==='month')calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+n,1);else calendarDate.setDate(calendarDate.getDate()+7*n)}if(a==='cal-today')calendarDate=new Date();if(a==='cal-month')calendarView='month';if(a==='cal-week')calendarView='week';if(a==='cal-day'){selectedDay=id;schedulePost=''}render();if(a==='cal-day')$('schedulePanel')?.scrollIntoView({behavior:'smooth'})}}catch(err){toast(err.message)}finally{b.disabled=false}},true);
window.addEventListener('beforeunload',e=>{if(formDirty||zipBusy){e.preventDefault();e.returnValue=''}});
schedulePost=null;

function directConnections(){return ['instagram','linkedin'].map(p=>`<section><h2>${p==='instagram'?'Instagram diretto · senza Pagina Facebook':'LinkedIn · profilo personale'}</h2><p>${p==='instagram'?'Richiede un account professionale. Il collegamento Facebook resta disponibile più sotto. Un blocco di sicurezza Instagram potrebbe impedire anche questo accesso.':'Profilo previsto: Pietro Lo Iacono (linkedin.com/in/lo-iacono-pietro/). Accesso con autorizzazione ufficiale. Le pagine aziendali richiedono permessi e configurazione dedicati.'}</p><p>${state.status[p+'_oauth_configured']?'App configurata: autorizza e poi conferma l’identità.':'Configurazione dell’app da completare; account non ancora collegato.'}</p><details><summary>Configurazione tecnica</summary><form data-form="direct-keys"><label>ID applicazione ${p}<input name="${p}_app_id" required></label><label>Segreto applicazione<input name="${p}_app_secret" type="password" autocomplete="off" required></label><button>Salva configurazione</button></form><p>Redirect: ${esc(location.origin+hubBase+'/oauth/'+p+'/callback')}</p></details><form data-form="direct-oauth" data-provider="${p}"><label>Sede<select name="office_id">${options(state.offices)}</select></label><button ${state.status[p+'_oauth_configured']?'':'disabled'}>Autorizza ${p==='instagram'?'Instagram':'LinkedIn'}</button></form>${action('direct-options',p,'Mostra account autorizzato')}<div id="direct-${p}"></div></section>`).join('')+`<section><h2>TikTok · automatico con Buffer</h2><p>Collega @credipass.aversa al tuo account Buffer gratuito, poi riusa l’autorizzazione Buffer già salvata oppure inserisci una chiave la prima volta. Il Social Hub invierà i contenuti agli orari del suo calendario.</p><p>Il piano gratuito Buffer prevede 3 canali e 10 post in coda per canale. Musica ed effetti da aggiungere nell’app richiedono pubblicazione assistita.</p><form data-form="buffer"><label>Sede<select name="office_id">${options(state.offices)}</select></label><label>Autorizzazione Buffer<select name="source_connection"><option value="">Inserisci una nuova chiave</option>${state.connections.filter(c=>c.auth_method==='buffer'&&c.expires_at>Date.now()/1000).map((c,i)=>`<option value="${esc(c.id)}" ${i===0?'selected':''}>Riusa Buffer già collegato · ${esc(c.name)}</option>`).join('')}</select></label><details><summary>Nuova chiave, solo se non ne hai già una</summary><label>Chiave API Buffer<input name="token" type="password" autocomplete="off"></label><label>Scadenza della chiave Buffer<input name="expiry" type="date"></label></details><button>Trova il mio TikTok</button><div class="buffer-options"></div></form>${state.connections.some(c=>c.platform==='TikTok'&&c.enabled)?`<details><summary>Prova il collegamento senza pubblicare</summary><form data-form="buffer-test"><label>Contenuto della libreria<select name="post_id">${options(state.posts.map(p=>({...p,name:officeName(p.office_id)+' · '+p.title})))}</select></label><p>Crea una bozza in Buffer: non la programma e non la pubblica.</p><button>Crea bozza di prova in Buffer</button></form></details>`:''}</section>`}
function assistedPanel(j){if(j.remote?.buffer_attempted)return '<p>Contenuto affidato a Buffer. <a href="https://publish.buffer.com/" target="_blank" rel="noopener">Controlla in Buffer</a> prima di creare un altro invio.</p>'; if(j.status==='manual_published')return `<p>Pubblicazione dichiarata da un operatore; non verificata tramite API. <a href="${esc(j.manual_url)}" target="_blank" rel="noopener">Vedi sul social</a></p>`;if(['draft','error','cancelled'].includes(j.status))return `<section><h3>Vuoi pubblicarlo tu?</h3><p>Prepara i file e il testo, poi completa l’invio sul social. L’orario in calendario sarà un promemoria.</p>${action('assist-job',j.id,'Prepara pubblicazione assistita')}</section>`;if(j.status!=='assisted')return '';const aversa=officeName(j.office_id).toLowerCase().includes('aversa');const home=j.channel.startsWith('Instagram')?(aversa?'https://www.instagram.com/credipass.aversa/':'https://www.instagram.com/'):j.channel==='TikTok'?(aversa?'https://www.tiktok.com/@credipass.aversa':'https://www.tiktok.com/'):j.channel==='LinkedIn'?(aversa?'https://www.linkedin.com/in/lo-iacono-pietro/':'https://www.linkedin.com/'):'https://www.facebook.com/';return `<section><h3>Pubblicazione assistita</h3><p>Nessun invio automatico. Controlla il profilo di destinazione sul social prima di pubblicare.</p><div class="actions">${action('copy-job',j.id,'1. Copia testo')}${(j.previews||[]).map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener" download>2. Apri / salva immagine ${i+1}</a>`).join('')}<a href="${home}" target="_blank" rel="noopener">3. Apri il social</a></div><p>Per Reel e video serve il video completo; la copertina non lo sostituisce.</p><form data-form="manual-published" data-id="${esc(j.id)}"><label>4. Dopo aver pubblicato, incolla il link del post<input type="url" name="url" placeholder="https://…" required></label><button>Confermo di averlo pubblicato</button></form><p class="muted">La conferma registra una tua dichiarazione, senza verificare l’invio tramite API.</p>${action('cancel',j.id,'Annulla promemoria')}</section>`}
document.addEventListener('click',async e=>{const b=e.target.closest('button'),a=b?.dataset.action,id=b?.dataset.id;if(!['direct-options','direct-select','assist-job','copy-job'].includes(a))return;e.stopImmediatePropagation();b.disabled=true;try{if(a==='direct-options'){const r=await api('oauth/'+id+'/options');$('direct-'+id).innerHTML=r.options.map(o=>`<p><b>${esc(o.name)}</b> · ${esc(o.external_id)} · ${esc(officeName(o.office_id))} <button data-action="direct-select" data-id="${esc(o.id)}" data-provider="${id}">Conferma questo account per la sede</button></p>`).join('')||'<p>Nessuna autorizzazione in attesa: completa prima l’accesso.</p>'}else if(a==='direct-select'){await api('oauth/'+b.dataset.provider+'/select',{session:id});await load();toast('Account confermato')}else if(a==='copy-job'){await navigator.clipboard.writeText(state.jobs.find(j=>j.id===id).body);toast('Testo copiato')}else{await api('job/action',{id,action:'assist'});await load();jobDetail(id)}}catch(err){toast(err.message)}finally{b.disabled=false}},true);

function officialSources(){return pageHead('Fonti Credipass Italia','Profili nazionali indicati da te come riferimento editoriale.')+`<section><p>Questi riferimenti non sono feed automatici e non sono account di pubblicazione di Aversa. Puoi aprire un post, recuperarne i materiali autorizzati e preparare il contenuto in Libreria. L’importazione automatica dai profili nazionali non è attiva.</p>${(state.official_sources||[]).map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a></p>`).join('')}</section>`}
function communityPage(inbox){const accounts=state.connections.filter(c=>c.enabled);return pageHead(inbox?'Inbox':'Analisi e report',inbox?'Tutte le conversazioni di Aversa, in un unico spazio.':'Il pubblico, i risultati e l’andamento dei tuoi contenuti.')+`<section id="communityPanel" data-inbox="${inbox}"><div class="community-toolbar"><label>Social<select id="communitySocial"><option value="">Tutti i social</option>${['Facebook','Instagram','LinkedIn','TikTok'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Account<select id="communityAccount">${inbox?'<option value="all">Tutti gli account Meta</option>':''}${options(accounts.map(c=>({...c,name:c.name+' · '+c.platform+' · '+officeName(c.office_id)})))}</select></label>${inbox?'<label>Cerca<input id="inboxSearch" placeholder="Nome del contatto"></label>':'<label>Periodo<select id="statsDays"><option value="7">Ultimi 7 giorni</option><option value="14">Ultimi 14 giorni</option><option value="28">Ultimi 28 giorni</option></select></label>'}<button type="button" data-community="load" class="secondary">↻ Aggiorna</button>${inbox?'':'<button type="button" data-report="print">Report PDF</button>'}</div><p class="sync-label">${inbox?'● Sincronizzazione automatica ogni minuto mentre l’inbox è aperta.':'● Caricamento automatico · dati restituiti dal social'}</p><div class="${inbox?'inbox-layout':'analytics-layout'}"><div id="communityResult" aria-live="polite"></div><div id="communityThread"></div></div><details class="community-help"><summary>Collegamenti e disponibilità dei dati</summary><p>Facebook e Instagram richiedono i permessi specifici. LinkedIn e TikTok non sono ancora integrati in questa sezione.</p><p>${inbox?'Sono mostrati fino a 25 conversazioni per account e 100 messaggi recenti per conversazione. Per altri risultati seleziona il singolo account. Allegati da aprire nel social; nessuna risposta automatica. La disponibilità dei messaggi dei clienti dipende dai permessi approvati da Meta.':'Il periodo riguarda le metriche di attività. Follower, Mi piace e numero di contenuti sono totali attuali. I dati non disponibili non vengono rappresentati come zero.'}</p>${state.actor.role==='admin'?'<button type="button" data-community="authorize">Rinnova i permessi dell’account selezionato</button>':''}</details></section>`}
document.addEventListener('change',e=>{if(e.target.id==='communityAccount'){ $('communityResult').textContent='';$('communityThread').textContent='';$('communityThread').dataset.ticket=''; }if(e.target.id==='communitySocial'){
 const list=state.connections.filter(c=>c.enabled&&(!e.target.value||c.platform===e.target.value));$('communityAccount').innerHTML=($('communityPanel').dataset.inbox==='true'?'<option value="all">Tutti gli account Meta</option>':'')+options(list.map(c=>({...c,name:c.name+' · '+officeName(c.office_id)})));$('communityResult').textContent='';$('communityThread').textContent='';$('communityThread').dataset.ticket='';
}});
function renderMessages(result,ticket){return `<h2>Conversazione</h2>${result.more?'<p>Mostrati solo i 100 messaggi più recenti.</p>':''}${result.messages.map(m=>`<article class="message-bubble ${m.own?'outgoing':'incoming'}"><strong>${m.own?'Tu':esc(m.from)}</strong> <small>${esc(m.time)}</small><p style="white-space:pre-wrap">${esc(m.text)}</p></article>`).join('')||'<p>Nessun messaggio restituito dal social.</p>'}<label>Risposta<textarea id="communityReply" maxlength="1000" placeholder="Scrivi qui la risposta"></textarea></label><button type="button" data-community="reply" data-ticket="${esc(ticket)}" data-request="${crypto.randomUUID()}">Invia risposta</button><p>Invio reale dal tuo account. Disponibile entro 24 ore dall’ultimo messaggio ricevuto, se consentito da Meta.</p>`}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-community]');if(!b)return;
 const panel=$('communityPanel'),result=$('communityResult'),thread=$('communityThread');if(!panel)return;
 const kind=b.dataset.community;const cid=$('communityAccount').value;
 const generation=crypto.randomUUID();if(kind==='load'||kind==='more')panel.dataset.generation=generation;
 b.disabled=true;
 try{
  if(kind==='authorize'){
   const c=state.connections.find(c=>c.id===cid);if(!c||!['Facebook','Instagram'].includes(c.platform))throw Error('Seleziona Facebook o Instagram');
   const r=await api(c.auth_method==='instagram_login'?'oauth/instagram/start':'oauth/start',{office_id:c.office_id,platform:c.platform,community:true});location.assign(r.url);return;
  }else if(kind==='load'||kind==='more'){
   if(!cid)throw Error('Nessun account collegato per questo social');
   if(kind==='more'||!thread.dataset.ticket)thread.textContent='';result.textContent='Sincronizzazione…';
   const inbox=panel.dataset.inbox==='true';let r;
   if(inbox&&cid==='all'){
    const accounts=state.connections.filter(c=>c.enabled&&['Facebook','Instagram'].includes(c.platform)&&(!$('communitySocial').value||c.platform===$('communitySocial').value));
    const results=await Promise.all(accounts.map(async c=>{try{const v=await api('community/inbox',{connection_id:c.id});return {items:v.items.map(x=>({...x,name:c.platform+' · '+x.name})),notice:v.after?c.name+': altre conversazioni disponibili selezionando il singolo account.':''}}catch(err){return {items:[],notice:c.name+': '+err.message}}}));
    r={items:results.flatMap(x=>x.items).sort((a,b)=>b.updated_time.localeCompare(a.updated_time)),after:'',notices:results.map(x=>x.notice).filter(Boolean)};
   }else r=await api(inbox?'community/inbox':'community/stats',{connection_id:cid,after:kind==='more'?b.dataset.after:'',days:Number($('statsDays')?.value||7)});
   if(!panel.isConnected||$('communityAccount').value!==cid||panel.dataset.generation!==generation)return;
   if(inbox)result.innerHTML=(r.notices||[]).map(n=>`<p class="warn">${esc(n)}</p>`).join('')+r.items.map(x=>`<p><button type="button" data-community="thread" data-ticket="${esc(x.ticket)}">${esc(x.name)}</button> <small>${esc(x.updated_time)}</small></p>`).join('')+(r.after?`<button type="button" data-community="more" data-after="${esc(r.after)}">Pagina successiva</button>`:'')+(r.items.length?'':'<p>Nessuna conversazione restituita. Alcune richieste o conversazioni potrebbero non essere esposte dalle API.</p>');
   else result.innerHTML=analyticsMarkup(r);
   if(inbox){const query=$('inboxSearch')?.value?.toLowerCase()||'';result.querySelectorAll(':scope>p').forEach(p=>p.hidden=!p.textContent.toLowerCase().includes(query));const ticket=thread.dataset.ticket;if(ticket&&!$('communityReply')?.value?.trim()){const messages=await api('community/messages',{ticket});if(panel.isConnected&&thread.dataset.ticket===ticket&&!$('communityReply')?.value?.trim()&&!document.querySelector('[data-community=reply]:disabled')){const scroll=thread.scrollTop;thread.innerHTML=renderMessages(messages,ticket);thread.scrollTop=scroll}}}

  }else if(kind==='thread'){
   thread.dataset.ticket=b.dataset.ticket;thread.textContent='Caricamento messaggi…';const r=await api('community/messages',{ticket:b.dataset.ticket});if(panel.isConnected&&thread.dataset.ticket===b.dataset.ticket)thread.innerHTML=renderMessages(r,b.dataset.ticket);
  }else if(kind==='reply'){
   const body=$('communityReply').value.trim();if(!body)throw Error('Scrivi la risposta prima di inviare');
   await api('community/reply',{ticket:b.dataset.ticket,body,request_id:b.dataset.request});toast('Risposta inviata');
   const r=await api('community/messages',{ticket:b.dataset.ticket});if(panel.isConnected&&thread.dataset.ticket===b.dataset.ticket)thread.innerHTML=renderMessages(r,b.dataset.ticket);
  }
 }catch(error){if(panel.isConnected){if(kind==='reply')toast(error.message+' Se l’esito è incerto, aggiorna la conversazione.');else (kind==='thread'?thread:result).textContent=error.message;}}
 finally{b.disabled=false;}
});

function analyticsMarkup(r){const explanations={'Follower':'Persone che seguono il profilo oggi. Non è la crescita nel periodo.','Mi piace alla pagina':'Totale attuale dei Mi piace alla pagina.','Contenuti':'Numero totale di contenuti del profilo.','Account raggiunti':'Account distinti raggiunti nel periodo. La somma dei giorni può contare più volte la stessa persona.','Visualizzazioni':'Quante volte i contenuti sono stati visualizzati, incluse le ripetizioni.'};return `<div class="report-heading"><h2>Il tuo pubblico, in numeri</h2><p><b>${esc($('communityAccount')?.selectedOptions[0]?.textContent||'')}</b></p><p>Ultimi ${r.days||7} giorni · aggiornato ${new Date(r.checked_at*1000).toLocaleString('it-IT')}</p></div><div class="metric-grid">${r.cards.map(c=>`<article class="metric-card"><span>${esc(c.label)}</span><strong>${typeof c.value==='number'?c.value.toLocaleString('it-IT'):'—'}</strong><small>${esc(c.period)}</small><p>${esc(explanations[c.label]||'')}</p></article>`).join('')}</div><section class="trend-card"><h2>Copertura giorno per giorno</h2><p>Account raggiunti su Instagram · i giorni senza dati non vengono convertiti in zero.</p>${trendChart(r.series||[])}<details><summary>Mostra i dati del grafico</summary><table><thead><tr><th>Giorno (fine intervallo Meta)</th><th>Account raggiunti</th></tr></thead><tbody>${(r.series||[]).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.value)}</td></tr>`).join('')}</tbody></table></details></section>${r.warnings.map(w=>`<p class="warn">${esc(w)}</p>`).join('')}`}
function trendChart(points){if(!points.length)return '<div class="chart-empty">Il social non ha restituito una serie giornaliera per questo account. Nessun andamento stimato.</div>';const max=Math.max(1,...points.map(x=>x.value));return `<div class="bar-chart" role="img" aria-label="Copertura giornaliera, valori disponibili anche nella tabella">${points.map(x=>`<div class="bar-column"><span>${esc(x.value)}</span><i style="height:${Math.max(0,x.value/max*180)}px"></i><small>${esc(x.date.slice(8,10)+'/'+x.date.slice(5,7))}</small></div>`).join('')}</div>`}
function adsPage(){return pageHead('ADS · Campagne','Uno spazio dedicato alla pubblicità, separato dai risultati organici.')+`<section><span class="badge">Collegamento pubblicitario da attivare</span><h2>Facebook e Instagram Ads</h2><p>I collegamenti delle pagine non autorizzano l’accesso agli account pubblicitari. Per importare campagne, spesa, copertura, clic e risultati occorre collegare un account Ads con i relativi permessi.</p><div class="metric-grid">${['Spesa','Impression','Clic','Costo per risultato'].map(x=>`<article class="metric-card"><span>${x}</span><strong>—</strong><small>Account Ads non collegato</small></article>`).join('')}</div><a class="button" href="https://adsmanager.facebook.com/" target="_blank" rel="noopener">Apri Gestione inserzioni Meta</a><p>Da questa sezione non vengono create campagne né avviate spese. L’integrazione dei dati Ads è il prossimo collegamento da completare.</p></section>`}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='approve-pending'){b.disabled=true;let ok=0,errors=[];try{for(const j of state.jobs.filter(j=>j.status==='draft')){try{await api('job/action',{id:j.id,action:'approve'});ok++}catch(err){errors.push(j.title+': '+err.message)}}await load();toast(`${ok} invii approvati. ${errors.length?errors.join(' · '):''}`)}finally{b.disabled=false}return}if(b.dataset.report==='print'){window.print();return}if(['trash-post','restore-post'].includes(b.dataset.action)){b.disabled=true;try{await api('post/action',{id:b.dataset.id,action:b.dataset.action==='trash-post'?'trash':'restore'});await load();toast('Libreria aggiornata. Le programmazioni esistenti restano nel calendario.')}catch(err){toast(err.message)}finally{b.disabled=false}}});
document.addEventListener('change',e=>{if(e.target.id==='batchAllPosts')document.querySelectorAll('[name=batchPost]').forEach(x=>x.checked=e.target.checked);if(['communityAccount','communitySocial','statsDays'].includes(e.target.id))document.querySelector('[data-community=load]')?.click()});
document.addEventListener('input',e=>{if(e.target.id==='inboxSearch')document.querySelectorAll('#communityResult>p').forEach(p=>p.hidden=!p.textContent.toLowerCase().includes(e.target.value.toLowerCase()))});
document.addEventListener('submit',async e=>{const f=e.target;if(f.dataset.form!=='batch-schedule')return;e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{const targets=[...f.querySelectorAll('[name=batchTarget]:checked')];if(!targets.length)throw Error('Seleziona almeno una destinazione');const posts=[...f.querySelectorAll('[name=batchPost]:checked')].map(o=>state.posts.find(p=>p.id===o.value));if(!posts.length)throw Error('Seleziona almeno un contenuto');if(new Set(posts.map(p=>p.office_id)).size>1)throw Error('Programma insieme i contenuti della stessa sede');const scheduled=new Date($('batchDate').value).toISOString();const r=await api('jobs/batch',{request_id:f.dataset.request,approve:$('batchApprove').checked,items:posts.flatMap((p,i)=>{const date=batchDateAt($('batchDate').value,$('batchSpacing').value,$('batchTimes').value,i);return targets.map(x=>({post_id:p.id,channel:x.dataset.channel,connection_id:x.value,scheduled:date.toISOString()}))})});schedulePost=null;calendarDate=new Date(scheduled);await load();toast(`${r.created} pubblicazioni aggiunte al calendario`)}catch(err){toast(err.message)}finally{b.disabled=false}});
setInterval(()=>{if(tab==='inbox'&&!document.hidden&&!$('communityReply')?.value?.trim()&&!document.querySelector('[data-community=reply]:disabled'))document.querySelector('[data-community=load]')?.click()},60000);
